try { created = $('Airtable - Create User').first().json.records?.[0]; } catch (error) { created = null; }
const record = found || created || null;
const fields = record?.fields || {};
const dailyRequests = Number(fields.daily_requests || 0);
const status = fields.status || 'free';
const spreadsheetId = String(fields.spreadsheet_id || '').trim();
return [{
  json: {
    record_id: record?.id || '',
    telegram_id: $node['Code - Normalize Photo'].json.telegram_id,
    chat_id: $node['Code - Normalize Photo'].json.chat_id,
    daily_requests: dailyRequests,
    status,
    request_log: String(fields.request_log || ''),
    email: String(fields.email || ''),
    spreadsheet_id: spreadsheetId,
    spreadsheet_url: String(fields.spreadsheet_url || ''),
    sheet_title: String(fields.sheet_title || ''),
    file_id: $node['Code - Normalize Photo'].json.file_id,
    missing_spreadsheet: !spreadsheetId,
    limit_exceeded: status === 'free' && dailyRequests >= 10
  }
}];

const binary = $input.first().binary?.data;
if (!binary) {
  throw new Error('No image binary metadata found');
}
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buffer || buffer.length === 0) {
  throw new Error('No image binary buffer found');
}
const mime = binary.mimeType || 'image/jpeg';
const imageUrl = 'data:' + mime + ';base64,' + buffer.toString('base64');
const today = new Date().toISOString().slice(0, 10);
const prompt = "Ты — аккуратный OCR-аналитик чеков и банковских транзакций.\n\nПроанализируй изображение: это может быть фото кассового чека, скриншот банковской операции, терминальный чек или онлайн-квитанция.\n\nВерни только строгий JSON без Markdown и без пояснений:\n{\n  \"date\": \"YYYY-MM-DD\",\n  \"merchant\": \"Название магазина/сервиса\",\n  \"amount\": 1250.00,\n  \"currency\": \"RUB\",\n  \"category\": \"Категория расходов\",\n  \"items_summary\": \"Краткий список покупок или суть транзакции\"\n}\n\nПравила:\n- Если дата не видна, используй сегодняшнюю дату из сообщения пользователя.\n- amount должен быть числом, без пробелов и символов валюты.\n- currency нормализуй как RUB, BYN, USD, EUR или другую ISO-подобную валюту.\n- Категорию определи самостоятельно: Продукты, Кафе, Транспорт, Такси, Маркетплейсы, Аптека, Связь, Подписки, Развлечения, Дом, Одежда, Другое.\n- Если магазин не виден, укажи \"Не распознано\".\n- Если сумму невозможно понять, amount = 0 и category = \"Требует проверки\"." + '\n\nСегодня: ' + today;
return [
  {
    json: {
      body: {
        model: 'gpt-4o',
        temperature: 0,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: 'You return only valid JSON.' },
          {
            role: 'user',
            content: [
              { type: 'text', text: prompt },
              { type: 'image_url', image_url: { url: imageUrl, detail: 'high' } }
            ]
          }
        ]
      },
      debug_binary_mime: mime,
      debug_binary_bytes: buffer.length
    }
  }
];

const raw = String($json.raw_ocr_text || $json.choices?.[0]?.message?.content || $json.output_text || $json.text || '').trim();
const COL_DATE = '\u0414\u0430\u0442\u0430';
const COL_MERCHANT = '\u041c\u0430\u0433\u0430\u0437\u0438\u043d/\u0421\u0435\u0440\u0432\u0438\u0441';
const COL_AMOUNT = '\u0421\u0443\u043c\u043c\u0430';
const COL_CURRENCY = '\u0412\u0430\u043b\u044e\u0442\u0430';
const COL_CATEGORY = '\u041a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f';
const COL_DETAILS = '\u041e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 \u043f\u043e\u043a\u0443\u043f\u043e\u043a';
function stripFences(value) {
  return value.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
}
function parseJson(value) {
  const cleaned = stripFences(value);
  try { return JSON.parse(cleaned); } catch (error) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (_) {}
    }
    throw new Error('OpenAI Vision did not return valid JSON');
  }
}
const data = parseJson(raw);
const today = new Date().toISOString().slice(0, 10);
const amount = Number(String(data.amount ?? 0).replace(',', '.').replace(/[^0-9.\-]/g, '')) || 0;
return [{
  json: {
    [COL_DATE]: String(data.date || today).slice(0, 10),
    [COL_MERCHANT]: String(data.merchant || '\u041d\u0435 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u043d\u043e').trim(),
    [COL_AMOUNT]: Math.round(amount * 100) / 100,
    [COL_CURRENCY]: String(data.currency || 'RUB').trim().toUpperCase(),
    [COL_CATEGORY]: String(data.category || '\u0414\u0440\u0443\u0433\u043e\u0435').trim(),
    [COL_DETAILS]: String(data.items_summary || '').trim(),
    raw_model_output: raw
  }
}];

