  json: { records: [{ id: record.id, fields: { daily_requests: 0, updated_at: new Date().toISOString() } }] }
}));

const trigger = $('Telegram Trigger').first().json;
const message = trigger.message || {};
const records = $json.records || [];
const record = records[0] || null;
const fields = record?.fields || {};
const text = String(message.text || message.caption || '').trim();
const emailMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const hasPhoto = Array.isArray(message.photo) && message.photo.length > 0;
const spreadsheetId = String(fields.spreadsheet_id || '').trim();
let route = 'fallback';
if (emailMatch) {
  route = 'create_sheet';
} else if (hasPhoto && spreadsheetId) {
  route = 'process_photo';
} else if (hasPhoto && !spreadsheetId) {
  route = 'ask_email';
} else if (text === '/start' && spreadsheetId) {
  route = 'fallback';
} else if (text === '/start' || text === '/new' || !spreadsheetId) {
  route = 'ask_email';
}
const telegramId = String(message.from?.id || '');
const firstName = String(message.from?.first_name || '').trim();
const username = String(message.from?.username || '').trim();
const safeName = (firstName || username || telegramId).replace(/[\\/:*?"<>|]/g, ' ').slice(0, 80).trim();
return [{
  json: {
    route,
    user_exists: Boolean(record?.id),
    record_id: record?.id || '',
    telegram_id: telegramId,
    chat_id: String(message.chat?.id || ''),
    username,
    first_name: firstName,
    email: emailMatch ? emailMatch[0].toLowerCase() : String(fields.email || ''),
    spreadsheet_id: spreadsheetId,
    spreadsheet_url: String(fields.spreadsheet_url || ''),
    sheet_title: '\u0420\u0430\u0441\u0445\u043e\u0434\u044b - ' + safeName,
    onboarding_status: String(fields.onboarding_status || '')
  }
}];

